// Renders the generated files of `pnpm schema:generate` from the zod schemas (docs/phase-1.md 3.4).
// Each target writes into its own folder of the repository, for example contracts/schemas/.
import { readdir, readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import * as prettier from "prettier";
import { z } from "zod";
import { eventTypes } from "../src/events.ts";
import { schemaEntries, type SchemaEntry } from "../src/registry.ts";
import { documentSamples, event, eventSamples, validData } from "../src/testing/samples.ts";
import { KOTLIN_DIR, renderKotlin } from "./kotlin.ts";

/** The root of the repository: the package `@aw/schema` is `shared/schema`. */
export const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");

/** The shared Prettier config (`@aw/config`), the same config that `pnpm format:check` uses. */
const prettierConfig = fileURLToPath(import.meta.resolve("@aw/config/prettier"));

export interface GeneratedFile {
  /** The path relative to repoRoot, with `/` separators. */
  path: string;
  content: string;
}

export interface Target {
  name: string;
  /** The folder that this target owns, relative to repoRoot. It holds only generated files. */
  dir: string;
  render(entries: SchemaEntry[]): Promise<GeneratedFile[]>;
}

const NOTE = "Generated by `pnpm schema:generate` from shared/schema/src. Do not edit.";

/** Formats a file with the Prettier config of the repository, so `pnpm format:check` passes. */
async function format(path: string, content: string): Promise<string> {
  const filepath = join(repoRoot, path);
  const options = (await prettier.resolveConfig(filepath, { config: prettierConfig })) ?? {};
  return prettier.format(content, { ...options, filepath });
}

/** JSON Schema 2020-12 from `z.toJSONSchema()`, one file per schema name. */
export const jsonSchemaTarget: Target = {
  name: "json-schema",
  dir: "contracts/schemas",
  async render(entries) {
    return Promise.all(
      entries.map(async (entry) => {
        // io "input": a field with a default is optional, because an older file can omit it.
        const { $schema, ...body } = z.toJSONSchema(entry.schema, {
          target: "draft-2020-12",
          io: "input",
        });
        const json = { $schema, title: entry.title, $comment: NOTE, ...body };
        const path = `${this.dir}/${entry.name}.schema.json`;
        return { path, content: await format(path, JSON.stringify(json)) };
      }),
    );
  },
};

/**
 * Kotlin data classes for android/shared (scripts/kotlin.ts). The Kotlin lint tasks skip this
 * folder, so the text is not formatted by a tool; the drift check compares it as rendered.
 */
export const kotlinTarget: Target = {
  name: "kotlin",
  dir: KOTLIN_DIR,
  render(entries) {
    return Promise.resolve(renderKotlin(entries));
  },
};

/**
 * The schema samples of src/testing/samples.ts as one JSON file, so the Kotlin tests run the same
 * valid and invalid values as the TypeScript schema tests.
 */
export const samplesTarget: Target = {
  name: "samples",
  dir: "contracts/samples",
  async render() {
    const json = {
      $comment: NOTE,
      documents: documentSamples.map((sample) => ({
        name: sample.name,
        schema: sample.schema,
        value: sample.value(),
        invalid_path: sample.invalidPath ?? null,
      })),
      events: eventSamples.map((sample) => ({
        name: sample.name,
        value: sample.value,
        invalid_path: sample.invalidPath ?? null,
      })),
      event_types: eventTypes.map((type) => ({
        type,
        valid: event(type, validData[type]),
        data_null: event(type, null),
      })),
      unknown_type: event("task.teleported", { to: "mars" }),
    };
    const path = `${this.dir}/schema-samples.json`;
    return [{ path, content: await format(path, JSON.stringify(json)) }];
  },
};

/** The targets of `pnpm schema:generate`. */
export const targets: Target[] = [jsonSchemaTarget, kotlinTarget, samplesTarget];

export async function renderAll(): Promise<GeneratedFile[]> {
  const files = await Promise.all(targets.map((target) => target.render(schemaEntries)));
  return files.flat().sort((a, b) => a.path.localeCompare(b.path));
}

async function listFiles(dir: string): Promise<string[]> {
  try {
    const entries = await readdir(join(repoRoot, dir), { recursive: true, withFileTypes: true });
    return entries
      .filter((e) => e.isFile())
      .map((e) =>
        join(e.parentPath, e.name)
          .slice(repoRoot.length + 1)
          .split("\\")
          .join("/"),
      );
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }
}

export interface DriftReport {
  missing: string[];
  stale: string[];
  extra: string[];
}

/** Compares the generated files on disk with a new render. */
export async function findDrift(): Promise<DriftReport> {
  const rendered = await renderAll();
  const onDisk = new Set((await Promise.all(targets.map((t) => listFiles(t.dir)))).flat());
  const report: DriftReport = { missing: [], stale: [], extra: [] };
  for (const file of rendered) {
    if (!onDisk.has(file.path)) {
      report.missing.push(file.path);
      continue;
    }
    onDisk.delete(file.path);
    const current = await readFile(join(repoRoot, file.path), "utf8");
    if (current !== file.content) report.stale.push(file.path);
  }
  report.extra = [...onDisk].sort();
  return report;
}
